CREATE TEMPORARY TABLE "PlayerAccountEvidence" AS SELECT "world", "characterId", min("accountId") AS "accountId" FROM "PlayerSnapshot" WHERE "accountId" <> 0 GROUP BY "world", "characterId" HAVING min("accountId") = max("accountId");--> statement-breakpoint
ALTER TABLE "PlayerAccountEvidence" ADD PRIMARY KEY ("world", "characterId");--> statement-breakpoint
CREATE TEMPORARY TABLE "PlayerNameEvidence" AS SELECT DISTINCT "world", "characterId", "name" FROM "PlayerSnapshot" WHERE "accountId" <> 0;--> statement-breakpoint
ALTER TABLE "PlayerNameEvidence" ADD PRIMARY KEY ("world", "characterId", "name");--> statement-breakpoint
ANALYZE "PlayerAccountEvidence";--> statement-breakpoint
ANALYZE "PlayerNameEvidence";--> statement-breakpoint
CREATE TEMPORARY TABLE "PlayerSnapshotIdentity" AS SELECT "candidate"."id", "candidate"."world", "candidate"."snapshotHash", "PlayerAccountEvidence"."characterId", "PlayerAccountEvidence"."accountId" FROM (SELECT "PlayerSnapshot"."id", "PlayerSnapshot"."world", "PlayerSnapshot"."snapshotHash", CASE WHEN "PlayerSnapshot"."createdAt" < '2026-11-03' AND EXISTS (SELECT 1 FROM "PlayerNameEvidence" WHERE "PlayerNameEvidence"."world" = "PlayerSnapshot"."world" AND "PlayerNameEvidence"."characterId" = "PlayerSnapshot"."characterId" * 10 AND "PlayerNameEvidence"."name" = "PlayerSnapshot"."name") AND NOT EXISTS (SELECT 1 FROM "PlayerNameEvidence" WHERE "PlayerNameEvidence"."world" = "PlayerSnapshot"."world" AND "PlayerNameEvidence"."characterId" = "PlayerSnapshot"."characterId" AND "PlayerNameEvidence"."name" = "PlayerSnapshot"."name") THEN "PlayerSnapshot"."characterId" * 10 ELSE "PlayerSnapshot"."characterId" END AS "characterId" FROM "PlayerSnapshot" WHERE "PlayerSnapshot"."accountId" = 0) AS "candidate" JOIN "PlayerAccountEvidence" ON "PlayerAccountEvidence"."world" = "candidate"."world" AND "PlayerAccountEvidence"."characterId" = "candidate"."characterId";--> statement-breakpoint
ALTER TABLE "PlayerSnapshotIdentity" ADD PRIMARY KEY ("id");--> statement-breakpoint
ANALYZE "PlayerSnapshotIdentity";--> statement-breakpoint
CREATE TEMPORARY TABLE "PlayerSnapshotMerge" AS SELECT "id", coalesce("existingId", "firstId") AS "survivorId" FROM (SELECT "PlayerSnapshotIdentity"."id", "PlayerSnapshot"."id" AS "existingId", min("PlayerSnapshotIdentity"."id") OVER (PARTITION BY "PlayerSnapshotIdentity"."world", "PlayerSnapshotIdentity"."accountId", "PlayerSnapshotIdentity"."characterId", "PlayerSnapshotIdentity"."snapshotHash") AS "firstId" FROM "PlayerSnapshotIdentity" LEFT JOIN "PlayerSnapshot" ON "PlayerSnapshot"."world" = "PlayerSnapshotIdentity"."world" AND "PlayerSnapshot"."accountId" = "PlayerSnapshotIdentity"."accountId" AND "PlayerSnapshot"."characterId" = "PlayerSnapshotIdentity"."characterId" AND "PlayerSnapshot"."snapshotHash" = "PlayerSnapshotIdentity"."snapshotHash") AS "grouped" WHERE "id" <> coalesce("existingId", "firstId");--> statement-breakpoint
ALTER TABLE "PlayerSnapshotMerge" ADD PRIMARY KEY ("id");--> statement-breakpoint
ANALYZE "PlayerSnapshotMerge";--> statement-breakpoint
UPDATE "LootPlayer" SET "playerSnapshotId" = "PlayerSnapshotMerge"."survivorId" FROM "PlayerSnapshotMerge" WHERE "LootPlayer"."playerSnapshotId" = "PlayerSnapshotMerge"."id";--> statement-breakpoint
DELETE FROM "LootMapPlayer" USING "PlayerSnapshotMerge" WHERE "LootMapPlayer"."playerSnapshotId" = "PlayerSnapshotMerge"."id" AND EXISTS (SELECT 1 FROM "LootMapPlayer" AS "other" LEFT JOIN "PlayerSnapshotMerge" AS "otherMerge" ON "otherMerge"."id" = "other"."playerSnapshotId" WHERE "other"."organizationLootRecordId" = "LootMapPlayer"."organizationLootRecordId" AND "other"."playerSnapshotId" <> "LootMapPlayer"."playerSnapshotId" AND coalesce("otherMerge"."survivorId", "other"."playerSnapshotId") = "PlayerSnapshotMerge"."survivorId" AND ("otherMerge"."id" IS NULL OR "other"."playerSnapshotId" < "LootMapPlayer"."playerSnapshotId"));--> statement-breakpoint
UPDATE "LootMapPlayer" SET "playerSnapshotId" = "PlayerSnapshotMerge"."survivorId" FROM "PlayerSnapshotMerge" WHERE "LootMapPlayer"."playerSnapshotId" = "PlayerSnapshotMerge"."id";--> statement-breakpoint
UPDATE "HeroSighting" SET "detectorCharacterSnapshotId" = "PlayerSnapshotMerge"."survivorId" FROM "PlayerSnapshotMerge" WHERE "HeroSighting"."detectorCharacterSnapshotId" = "PlayerSnapshotMerge"."id";--> statement-breakpoint
UPDATE "HeroSightingClaim" SET "characterSnapshotId" = "PlayerSnapshotMerge"."survivorId" FROM "PlayerSnapshotMerge" WHERE "HeroSightingClaim"."characterSnapshotId" = "PlayerSnapshotMerge"."id";--> statement-breakpoint
DELETE FROM "PlayerSnapshot" USING "PlayerSnapshotMerge" WHERE "PlayerSnapshot"."id" = "PlayerSnapshotMerge"."id" AND NOT EXISTS (SELECT 1 FROM "Timer" WHERE "Timer"."actorCharacterSnapshotId" = "PlayerSnapshot"."id") AND NOT EXISTS (SELECT 1 FROM "TimerHistoryEntry" WHERE "TimerHistoryEntry"."actorCharacterSnapshotId" = "PlayerSnapshot"."id") AND NOT EXISTS (SELECT 1 FROM "TimerHistoryEntry" WHERE "TimerHistoryEntry"."timerActorCharacterSnapshotId" = "PlayerSnapshot"."id");--> statement-breakpoint
UPDATE "TimerHistoryEntry" SET "actorCharacterSnapshotId" = "PlayerSnapshotMerge"."survivorId" FROM "PlayerSnapshotMerge" WHERE "TimerHistoryEntry"."actorCharacterSnapshotId" = "PlayerSnapshotMerge"."id";--> statement-breakpoint
UPDATE "TimerHistoryEntry" SET "timerActorCharacterSnapshotId" = "PlayerSnapshotMerge"."survivorId" FROM "PlayerSnapshotMerge" WHERE "TimerHistoryEntry"."timerActorCharacterSnapshotId" = "PlayerSnapshotMerge"."id";--> statement-breakpoint
UPDATE "Timer" SET "actorCharacterSnapshotId" = "PlayerSnapshotMerge"."survivorId" FROM "PlayerSnapshotMerge" WHERE "Timer"."actorCharacterSnapshotId" = "PlayerSnapshotMerge"."id";--> statement-breakpoint
DELETE FROM "PlayerSnapshot" USING "PlayerSnapshotMerge" WHERE "PlayerSnapshot"."id" = "PlayerSnapshotMerge"."id";--> statement-breakpoint
UPDATE "PlayerSnapshot" SET "accountId" = "PlayerSnapshotIdentity"."accountId", "characterId" = "PlayerSnapshotIdentity"."characterId" FROM "PlayerSnapshotIdentity" WHERE "PlayerSnapshot"."id" = "PlayerSnapshotIdentity"."id" AND NOT EXISTS (SELECT 1 FROM "PlayerSnapshotMerge" WHERE "PlayerSnapshotMerge"."id" = "PlayerSnapshotIdentity"."id");--> statement-breakpoint
DROP TABLE "PlayerSnapshotMerge";--> statement-breakpoint
DROP TABLE "PlayerSnapshotIdentity";--> statement-breakpoint
DROP TABLE "PlayerNameEvidence";--> statement-breakpoint
DROP TABLE "PlayerAccountEvidence";
